  {json:{case_id:'M5-INT-ORDER',mode:'synthetic',message:'Where is my order and when will it arrive? Order No 123456.'}},
  {json:{case_id:'M5-INT-PAYMENT',mode:'synthetic',message:'Can I pay in installments or change my payment method?'}},
  {json:{case_id:'M5-INT-COMPLAINT',mode:'synthetic',message:'I received the wrong item and want to file a complaint.'}},
  {json:{case_id:'M5-INT-OTHER',mode:'synthetic',message:'What are your store opening hours?'}}
];

const raw = String($json.message || '');
const pii = [];
const safe = raw
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, () => { pii.push('email'); return '[EMAIL]'; })
  .replace(/(?:\+?\d[\d ().-]{7,}\d)/g, () => { pii.push('phone'); return '[PHONE]'; })
  .replace(/(?:No\s*\d{5,}|\b\d{5,}\b)/gi, () => { pii.push('order_reference'); return '[ORDER_REF]'; });
const { message: _rawMessage, ...safeFields } = $json;
return { json: { ...safeFields, message_redacted: safe, pii_types: [...new Set(pii)], raw_message_retained: false } };

const source = $('M5 — Normalize Supabase RAG evidence').item.json;
const raw = String($json.text ?? $json.output ?? $json.response ?? '');
let parsed = null;
try { const match = raw.match(/\{[\s\S]*\}/); if (match) parsed = JSON.parse(match[0]); } catch {}
const intent = String(source.intent || 'other');
const allowed = new Set(['order_status','returns','warranty']);
const shapeOk = Boolean(parsed && parsed.intent === intent && Array.isArray(parsed.evidence_ids) && Array.isArray(parsed.issues) && typeof parsed.needs_human === 'boolean' && typeof parsed.draft === 'string' && Number.isFinite(Number(parsed.confidence)));
const draft = shapeOk ? String(parsed.draft) : '';
const evidenceIds = shapeOk ? parsed.evidence_ids.filter(x => typeof x === 'string' && x.trim()) : [];
const issues = shapeOk ? parsed.issues.map(String) : ['specialist_invalid_json_or_schema'];
const pii = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}|(?:\+?\d[\d ().-]{7,}\d)/i.test(draft);
const evidenceSufficient = source.evidence_sufficient === true && evidenceIds.length > 0;
const unsupportedClaims = shapeOk ? (Array.isArray(parsed.unsupported_claims) ? parsed.unsupported_claims : []) : [];
return {json:{...source, agent:intent+'_agent_llm', specialist_model_output_valid:shapeOk && allowed.has(intent), answer_mode:'human_review_draft', draft:pii?'':draft, evidence_ids:evidenceIds, evidence_sufficient:evidenceSufficient, confidence:shapeOk?Number(parsed.confidence):0, needs_human:true, unsupported_claims:unsupportedClaims, specialist_issues:[...issues,...(pii?['pii_in_draft']:[])], specialist_raw_output:raw}};

const original = $('OpenRouter classifier + rules fallback').item.json;
const response = $input.item.json;
let rag;
try { rag = typeof response.ragRaw === 'string' ? JSON.parse(response.ragRaw) : response.ragRaw; }
catch (error) { rag = { hits: [], retrieval_method: 'Supabase pgvector response parse error', error: String(error) }; }
const hits = Array.isArray(rag?.hits) ? rag.hits : [];
const approved = hits.filter(hit => hit?.policy_eligible === true && hit?.fixture_only !== true && typeof hit?.source_id === 'string' && hit?.intent === original.intent);
return { json: {
  ...original,
  retrieval_hits: hits,
  retrieval_hit_ids: hits.map(hit => String(hit?.source_id || '')).filter(Boolean),
  approved_evidence: approved,
  evidence_ids: approved.map(hit => hit.source_id),
  evidence_sufficient: approved.length > 0,
  retrieval_intent_filter: original.intent,
  retrieval_method: rag?.retrieval_method || 'FastEmbed + Supabase pgvector',
  retrieval_backend: rag?.backend || 'Supabase Postgres + pgvector',
  retrieval_production_eligible: rag?.production_eligible === true,
  side_effects_allowed: false
} };
